from django.contrib.auth.hashers import make_password

ACTION = "l06_migration_mot_de_passe_provisoire"


def invalider_provisoires(apps, schema_editor):
    """Le mot de passe provisoire est supprimé (AC-16) : un compte qui en portait un reçoit un mot de passe inutilisable ;
    son titulaire repasse par une réinitialisation par code. Aucune connexion ne reste ouverte par un ancien provisoire."""
    UserProfile = apps.get_model("accounts", "UserProfile")
    AuditLog = apps.get_model("accounts", "AuditLog")
    User = apps.get_model("auth", "User")
    for profil in UserProfile.objects.filter(mot_de_passe_provisoire=True):
        User.objects.filter(pk=profil.user_id).update(password=make_password(None))
        AuditLog.objects.create(actor=None, action=ACTION, target_user_id=profil.user_id, details="mot de passe provisoire invalidé")



